inputs:
  python-version:
    description: Python version to install and use.
    required: false
    default: "3.11"

runs:
  using: composite
  steps:
    - name: Install uv
      uses: astral-sh/setup-uv@v5
      with:
        version: "0.13.0"
        enable-cache: true

    - name: Set up Python
      run: uv python install ${{ inputs.python-version }}
      shell: bash

    - name: Install dependencies
      run: uv sync --all-packages --locked
      shell: bash
      env:
